#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// Spinner's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/spinner.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// Whether the spinner shows and turns; an inactive spinner draws nothing and reports no busy state.
template <typename Declaring>
struct SpinnerActiveCapability {
    PropertyCell<bool, SpinnerActiveCapability<Declaring>> active{true};

    static void assign(SpinnerActiveCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.active), incoming);
        if (!capability.active.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.active));
    }
};

// Every Spinner capability, in the order the declaring class takes them.
template <typename Declaring>
struct SpinnerCapabilities : public SpinnerActiveCapability<Declaring> {};

} // namespace gui_forms
